import { assert, expect, it } from "vitest";
import { getEvalsAsRecordViaStorage, loadFixture } from "./test-utils.js";

it("Should report traces from generateText using traceAISDKModel", async () => {
  await using fixture = await loadFixture("ai-sdk-traces");

  await fixture.run({
    mode: "run-once-and-exit",
  });

  const evals = await getEvalsAsRecordViaStorage(fixture.storage);

  expect(evals["AI SDK Traces"]![0]?.results[0]?.traces).toHaveLength(1);

  const trace = evals["AI SDK Traces"]![0]?.results[0]?.traces[0];
  expect(trace?.output).toMatchObject({
    text: "Hello, world!",
    toolCalls: [
      {
        input: "{}",
        toolCallId: "abc",
        toolName: "myToolCall",
      },
    ],
  });
});

it("Should report traces from streamText using traceAISDKModel", async () => {
  await using fixture = await loadFixture("ai-sdk-traces-stream");

  await fixture.run({
    mode: "run-once-and-exit",
  });

  const evals = await getEvalsAsRecordViaStorage(fixture.storage);

  const traces = evals["AI SDK Traces"]![0]?.results[0]?.traces;

  assert(traces?.[0], "Expected a trace to be reported");

  expect(traces?.[0].input_tokens).toEqual(3);
  expect(traces?.[0].output_tokens).toEqual(10);
  expect(traces?.[0].total_tokens).toEqual(14);
});

import { wrapLanguageModel, type LanguageModel } from "ai";
import {
  type LanguageModelV2,
  type LanguageModelV2CallOptions,
} from "@ai-sdk/provider";
import { createHash } from "node:crypto";

const createKey = (params: LanguageModelV2CallOptions) => {
  return createHash("sha256").update(JSON.stringify(params)).digest("hex");
};

const createResultFromCachedObject = (
  obj: any
): Awaited<ReturnType<LanguageModelV2["doGenerate"]>> => {
  if (obj?.response?.timestamp) {
    obj.response.timestamp = new Date(obj.response.timestamp);
  }
  return obj as any;
};

export type StorageValue = string | number | null | object;

export type CacheStore = {
  get: (key: string) => Promise<StorageValue>;
  set: (key: string, value: StorageValue) => Promise<void>;
};

export const cacheModel = (
  model: LanguageModelV2,
  storage: CacheStore
): LanguageModelV2 => {
  return wrapLanguageModel({
    model,
    middleware: {
      wrapGenerate: async (opts) => {
        const key = createKey(opts.params);

        const resultFromCache = await storage.get(key);

        if (resultFromCache && typeof resultFromCache === "object") {
          const result = createResultFromCachedObject(resultFromCache);

          // Reset the tokens to 0 to show in the UI
          // that they were cached.
          result.usage.inputTokens = 0;
          result.usage.outputTokens = 0;
          result.usage.totalTokens = 0;

          return result;
        }

        const generated = await opts.doGenerate();

        await storage.set(key, JSON.stringify(generated));

        return generated;
      },
    },
  });
};

import { streamText, simulateReadableStream } from "ai";
import { MockLanguageModelV2 } from "ai/test";
import { Levenshtein } from "autoevals";
import { evalite } from "evalite";
import { traceAISDKModel } from "evalite/ai-sdk";

const model = new MockLanguageModelV2({
  doStream: async (options) => ({
    stream: simulateReadableStream({
      chunks: [
        { type: "text-delta", id: "1", delta: "Hello" },
        { type: "text-delta", id: "1", delta: ", " },
        { type: "text-delta", id: "1", delta: `world!` },
        {
          type: "finish",
          finishReason: "stop",
          logprobs: undefined,
          usage: { outputTokens: 10, inputTokens: 3, totalTokens: 14 },
        },
      ],
    }),
    rawCall: { rawPrompt: null, rawSettings: {} },
    request: undefined,
    response: undefined,
  }),
});

const tracedModel = traceAISDKModel(model);

evalite("AI SDK Traces", {
  data: () => {
    return [
      {
        input: "abc",
        expected: "abcdef",
      },
    ];
  },
  task: async (input) => {
    const result = await streamText({
      model: tracedModel,
      system: "Test system",
      prompt: input,
    });
    return result.textStream;
  },
  scorers: [Levenshtein],
});

