      const result = await storage.results.create({
        evalId: eval1.id,
        order: 0,
        input: { test: "input" },
        expected: { test: "expected" },
        output: { test: "output" },
        duration: 100,
        status: "success",
        renderedColumns: [{ label: "col1", value: "val1" }],
